      {
        "text": "查询全球使用AI最多的职业/行业",
        "dimensions": ["GOAL"],
        "evidence": [
          {"sourceId": "rawPrompt", "quote": "请帮我查询全球使用AI最多的职业/行业"}
        ]
      },
      {
        "text": "最终给出全球使用AI最多的职业/行业的查询结果",
        "dimensions": ["GOAL"],
